async function api(path, options = {}) {
  const response = await fetch(path, { credentials: 'same-origin', ...options, headers: { ...(options.body instanceof FormData ? {} : options.body && !options.headers?.['Content-Type'] ? { 'Content-Type': 'application/json' } : {}), ...(options.headers || {}) } });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || 'A operação não pôde ser concluída.');
  return data;
}
const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[character]));
const formatDate = value => value ? new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short',timeZone:'America/Sao_Paulo' }).format(value) : '—';
const since = value => { if (!value) return 'Nunca conectado'; const seconds = Math.max(0, Math.floor((Date.now() - value) / 1000)); return seconds < 8 ? 'Agora mesmo' : seconds < 60 ? `há ${seconds}s` : seconds < 3600 ? `há ${Math.floor(seconds / 60)} min` : `há ${Math.floor(seconds / 3600)} h`; };
const fileSize = bytes => bytes < 1024 * 1024 ? `${Math.ceil(bytes / 1024)} KB` : `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
function toast(message, error = false) { const box = document.createElement('div'); box.className = `toast${error ? ' error' : ''}`; box.textContent = message; $('#toasts').append(box); setTimeout(() => box.remove(), 5000); }
function mediaPreview(item, muted = true) { if (!item) return `<div class="mini-thumb">${icon('image')}</div>`; if (item.kind === 'video') return `<video src="${escapeHtml(item.url)}" ${muted ? 'muted' : ''} preload="metadata"></video>`; if (['image','product_image'].includes(item.kind)) return `<img src="${escapeHtml(item.url)}" alt="${escapeHtml(item.name)}">`; const c = item.config || {}; return `<div class="virtual-thumb kind-${escapeHtml(item.kind)}">${icon(item.kind === 'youtube' ? 'video' : item.kind === 'web' ? 'link' : 'image')}<strong>${escapeHtml(c.title || c.city || item.name)}</strong><small>${escapeHtml(item.kind === 'offer' ? money(c.price) : contentLabel(item.kind))}</small></div>`; }
function openModal(content, className = '') { if (modal.dataset.busy === 'true') return; modal.className = className; modal.innerHTML = content; modal.showModal(); return modal; }
function closeModal() { if (modal.dataset.busy === 'true') return; modal.close(); modal.innerHTML = ''; }
modal.addEventListener('click', event => { if (event.target === modal) closeModal(); });
modal.addEventListener('cancel', event => { event.preventDefault(); closeModal(); });
document.addEventListener('keydown', event => { if (event.key === 'Escape' && modal.open && !document.querySelector('dialog.image-bank-dialog[open]')) { event.preventDefault(); closeModal(); } });

