function render() { campaigns.dispose(); imageBank.disposePanel(); for (const link of document.querySelectorAll('.nav-link')) link.classList.toggle('active', link.dataset.page === state.page); const views = { dashboard: renderDashboard, points: renderPoints, media: renderMedia, playlists: renderPlaylists, reports: renderReports, campaigns: () => {void campaigns.render($('#page'));}, logs: renderLogs, products: () => {void catalog.render();}, 'image-bank': () => imageBank.mountPanel($('#page'),{heading:setPageTitle('Banco de imagens','Sincronize fotos reais de produtos e escolha as imagens usadas nos templates.')}) }; (views[state.page] || views.dashboard)(); }

function bindCommon() { for(const element of document.querySelectorAll('[data-attach-content]')) element.onclick=()=>library.attach(state.media.find(item=>item.id===element.dataset.attachContent)); for(const element of document.querySelectorAll('[data-media-policy]')) element.onclick=()=>mediaPolicyModal(state.media.find(item=>item.id===element.dataset.mediaPolicy)); for(const element of document.querySelectorAll('[data-monitor]')) element.onclick=()=>showMonitor(element.dataset.monitor); for (const element of document.querySelectorAll('[data-page]')) element.onclick = event => { event.preventDefault(); state.page = element.dataset.page; history.pushState(null,'','#'+state.page); render(); $('#sidebar')?.classList.remove('mobile-open'); }; for (const element of document.querySelectorAll('[data-new-point]')) element.onclick = () => pointModal(); for (const element of document.querySelectorAll('[data-edit-point]')) element.onclick = () => pointModal(state.points.find(p => p.id === element.dataset.editPoint)); for (const element of document.querySelectorAll('[data-delete-point]')) element.onclick = () => deletePoint(element.dataset.deletePoint); for (const element of document.querySelectorAll('[data-pair]')) element.onclick = () => pairModal(element.dataset.pair); for (const element of document.querySelectorAll('[data-unpair]')) element.onclick = () => unpairPoint(element.dataset.unpair); for (const element of document.querySelectorAll('[data-refresh-point]')) element.onclick = () => refreshPoint(element.dataset.refreshPoint); for (const element of document.querySelectorAll('[data-preview-media]')) element.onclick = () => previewMedia(element.dataset.previewMedia); for (const element of document.querySelectorAll('[data-delete-media]')) element.onclick = () => deleteMedia(element.dataset.deleteMedia); for (const element of document.querySelectorAll('[data-edit-playlist]')) element.onclick = () => playlistModal(state.playlists.find(p => p.id === element.dataset.editPlaylist)); for (const element of document.querySelectorAll('[data-publish]')) element.onclick = () => publishPlaylist(element.dataset.publish); for (const element of document.querySelectorAll('[data-delete-playlist]')) element.onclick = () => deletePlaylist(element.dataset.deletePlaylist); }
function pointModal(existing) { const point = existing || { name: '', location: '', playlistId: '', fit: 'contain' }; openModal(`<form id="point-form"><div class="modal-head"><h2>${existing ? 'Editar ponto' : 'Adicionar ponto'}</h2><button type="button" class="icon-button" data-close>${icon('x')}</button></div><div class="modal-body"><label class="field"><span>Nome do ponto</span><input name="name" required maxlength="120" value="${escapeHtml(point.name)}" placeholder="Ex.: Recepção"></label><label class="field"><span>Local</span><input name="location" maxlength="160" value="${escapeHtml(point.location)}" placeholder="Ex.: Loja centro"></label><label class="field"><span>Playlist atribuída</span><select name="playlistId"><option value="">Nenhuma playlist por enquanto</option>${state.playlists.map(p => `<option value="${p.id}" ${p.id === point.playlistId ? 'selected' : ''}>${escapeHtml(p.name)}${p.publishedVersion ? ` · v${p.publishedVersion}` : ' · ainda não publicada'}</option>`).join('')}</select><small>O ponto reproduz a última versão publicada desta playlist.</small></label><label class="field"><span>Ajuste na tela</span><select name="fit"><option value="contain" ${point.fit === 'contain' ? 'selected' : ''}>Mostrar inteiro, com margens quando necessário</option><option value="cover" ${point.fit === 'cover' ? 'selected' : ''}>Preencher toda a tela, podendo cortar bordas</option></select></label>${settingFields(point.settings)}<p class="form-error"></p></div><div class="modal-footer"><button type="button" class="btn" data-close>Cancelar</button><button class="btn primary" type="submit">${existing ? 'Salvar alterações' : 'Criar ponto'}</button></div></form>`); $('[data-close]', modal).onclick = closeModal; $('#point-form').onsubmit = async event => { event.preventDefault(); const submittedForm = event.currentTarget; const button = $('[type=submit]', submittedForm); button.disabled = true; try { const value = Object.fromEntries(new FormData(submittedForm));value.settings={orientation:value.orientation,kiosk:submittedForm.elements.kiosk.checked,progress:submittedForm.elements.progress.checked}; await api(existing ? `/api/points/${existing.id}` : '/api/points', { method: existing ? 'PUT' : 'POST', body: JSON.stringify(value) }); closeModal(); await refresh(); toast(existing ? 'Ponto atualizado.' : 'Ponto cadastrado. Abra o player para gerar um código de vínculo.'); } catch (error) { $('.form-error', submittedForm).textContent = error.message; } finally { button.disabled = false; } }; }
function pairModal(pointId) { const point = state.points.find(p => p.id === pointId); openModal(`<form id="pair-form"><div class="modal-head"><h2>Vincular ${escapeHtml(point.name)}</h2><button type="button" class="icon-button" data-close>${icon('x')}</button></div><div class="modal-body"><p class="modal-note">Abra <strong>/player</strong> no dispositivo que funcionará como tela. Digite abaixo o código de seis caracteres mostrado nele.</p><label class="field"><span>Código de vínculo</span><input class="pair-code" name="code" required maxlength="6" pattern="[A-Za-z0-9]{6}" autocomplete="off" spellcheck="false" placeholder="ABC123"></label><p class="form-error"></p></div><div class="modal-footer"><button type="button" class="btn" data-close>Cancelar</button><button class="btn primary" type="submit">${icon('link')} Vincular player</button></div></form>`); $('[data-close]', modal).onclick = closeModal; const input = $('input', modal); input.focus(); $('#pair-form').onsubmit = async event => { event.preventDefault(); const submittedForm = event.currentTarget; const button = $('[type=submit]', submittedForm); button.disabled = true; try { await api(`/api/points/${pointId}/pair`, { method: 'POST', body: JSON.stringify({ code: input.value }) }); closeModal(); await refresh(); toast('Player vinculado. Ele receberá a próxima publicação disponível.'); } catch (error) { $('.form-error', submittedForm).textContent = error.message; } finally { button.disabled = false; } }; }
async function unpairPoint(id) { const p = state.points.find(point => point.id === id); if (!confirm(`Desvincular o player de “${p.name}”? O dispositivo poderá gerar outro código.`)) return; try { await api(`/api/points/${id}/unpair`, { method: 'POST' }); await refresh(); toast('Player desvinculado.'); } catch (error) { toast(error.message, true); } }
async function refreshPoint(id) { try { await api(`/api/points/${id}/refresh`, { method: 'POST' }); toast('Atualização solicitada. O player aplica o comando na próxima sincronização.'); } catch (error) { toast(error.message, true); } }
async function deletePoint(id) { const p = state.points.find(point => point.id === id); if (!confirm(`Excluir o ponto “${p.name}”? Essa ação também desvincula o player atual.`)) return; try { await api(`/api/points/${id}`, { method: 'DELETE' }); await refresh(); toast('Ponto excluído.'); } catch (error) { toast(error.message, true); } }
