 openModal(`<form id="content-form"><div class="modal-head"><h2>${existing ? 'Editar conteúdo' : 'Criar conteúdo'}</h2><button type="button" class="icon-button" data-close>${icon('x')}</button></div><div class="modal-body"><label class="field"><span>Nome na biblioteca</span><input name="name" required maxlength="120" value="${escapeHtml(existing?.name)}" placeholder="Ex.: Oferta da semana"></label><label class="field"><span>Tipo de conteúdo</span><select name="kind" ${existing ? 'disabled' : ''}>${kinds.map(([kind,label]) => `<option value="${kind}" ${selected === kind ? 'selected' : ''}>${label}</option>`).join('')}</select></label><div id="content-fields"></div><p class="form-error" role="alert"></p></div><div class="modal-footer"><button type="button" class="btn" data-close>Cancelar</button><button class="btn primary" type="submit">Salvar conteúdo</button></div></form>`);
 for (const button of modal.querySelectorAll('[data-close]')) button.onclick = closeModal;
 const form = $('#content-form');
