  const cycle = posterCycle(readRows().filter(row => row.name && Number.isFinite(row.price)), seconds, $('[name=layout]',form)?.value);
  target.textContent = !cycle.items ? 'Adicione ao menos um produto ativo para calcular o ciclo.' : cycle.rotates ? `${cycle.items} produto(s) ativo(s) × ${seconds}s = ${durationLabel(cycle.seconds)} por ciclo completo.` : `${cycle.items} produto(s) ativo(s) na grade; este layout não alterna produtos automaticamente.`;
